import{_ as r,o as a,c as t,ai as l}from"./chunks/framework.iNbpOH0p.js";const c=JSON.parse('{"title":"数据可视化与图表","description":"","frontmatter":{},"headers":[],"relativePath":"doc/awesome-vue/数据可视化与图表.md","filePath":"doc/awesome-vue/数据可视化与图表.md"}'),i={name:"doc/awesome-vue/数据可视化与图表.md"};function h(o,e,n,s,u,b){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="数据可视化与图表" tabindex="-1">数据可视化与图表 <a class="header-anchor" href="#数据可视化与图表" aria-label="Permalink to “数据可视化与图表”">​</a></h1><h2 id="数据可视化" tabindex="-1">数据可视化 <a class="header-anchor" href="#数据可视化" aria-label="Permalink to “数据可视化”">​</a></h2><ul><li><a href="https://github.com/d3/d3" target="_blank" rel="noreferrer">D3.js</a> ⭐ 108k — 数据驱动文档可视化库，通过操作 DOM 元素实现数据到图形的映射，提供数据绑定、SVG 渲染和强大的数据转换能力，是众多可视化库的底层基础</li><li><a href="https://github.com/chartjs/Chart.js" target="_blank" rel="noreferrer">Chart.js</a> ⭐ 67k — 基于 HTML5 Canvas 的轻量级图表库，支持 8 种基础图表类型，体积小巧约 60KB，提供响应式设计和动画效果</li><li><a href="https://github.com/apache/echarts" target="_blank" rel="noreferrer">Apache ECharts</a> ⭐ 57k — Apache 基金会开源的可视化图表库，提供 60+ 图表类型，支持大数据量渲染、移动端适配和丰富的交互功能</li><li><a href="https://github.com/recharts/recharts" target="_blank" rel="noreferrer">Recharts</a> ⭐ 20k — 基于 React 和 D3 的声明式图表库，支持丰富的图表类型和响应式设计，可通过适配方案在 Vue 项目中使用</li><li><a href="https://github.com/rough-stuff/rough" target="_blank" rel="noreferrer">Rough.js</a> ⭐ 20k — 手绘风格图形库，体积小巧约 9KB 压缩后，支持 Canvas 和 SVG 渲染，可绘制线条、曲线、多边形等基础图形并添加手绘风格填充效果，可集成到 Vue 项目中</li><li><a href="https://github.com/plotly/plotly.js" target="_blank" rel="noreferrer">Plotly.js</a> ⭐ 18k — 基于 D3.js 和 stack.gl 的高级图表库，支持 40+ 图表类型包括 3D 图、统计图、科学图表和 SVG 地图，提供缩放、平移等交互功能，可集成到 Vue 项目中</li><li><a href="https://github.com/dream-num/Luckysheet" target="_blank" rel="noreferrer">Luckysheet</a> ⭐ 16k — 开源在线电子表格，功能强大配置简单，支持公式计算、数据透视表、图表、协同编辑和 Excel 导入导出，可集成到 Vue 项目中</li><li><a href="https://github.com/antvis/g2" target="_blank" rel="noreferrer">@antv/g2</a> ⭐ 16k — 蚂蚁集团 AntV 可视化语法引擎，基于图形语法理论构建，提供声明式图表语法和高度可定制的可视化能力</li><li><a href="https://github.com/apexcharts/apexcharts.js" target="_blank" rel="noreferrer">ApexCharts</a> ⭐ 15k — 基于 SVG 的现代交互式图表库，支持 20+ 图表类型包括柱状图、折线图、面积图、饼图、散点图、热力图等，提供丰富的动画和主题定制</li><li><a href="https://github.com/plouc/nivo" target="_blank" rel="noreferrer">Nivo</a> ⭐ 15k — 基于 React 和 D3 的富图表库，提供 30+ 图表类型，可通过封装集成到 Vue 项目，支持 SVG/Canvas/HTML 渲染</li><li><a href="https://github.com/vega/vega" target="_blank" rel="noreferrer">vega</a> ⭐ 12k — 声明式可视化语法库，通过 JSON 配置定义交互式图形，支持复杂数据转换和可视化组合，是 Vega-Lite 的底层引擎</li><li><a href="https://github.com/didi/LogicFlow" target="_blank" rel="noreferrer">LogicFlow</a> ⭐ 10k — 滴滴开源的流程图编辑框架，支持自定义节点、边样式和插件扩展，适用于 BPMN 流程设计、审批流程等场景</li><li><a href="https://github.com/DataV-Team/DataV/" target="_blank" rel="noreferrer">DataV</a> ⭐ 10k — 基于 Vue 的数据可视化大屏组件库，提供丰富的图表组件和可视化效果，适合搭建数据大屏展示系统</li><li><a href="https://github.com/antvis/f2" target="_blank" rel="noreferrer">@antv/f2</a> ⭐ 6k — 蚂蚁集团 AntV 移动端可视化库，基于 Canvas 渲染，专为移动端 H5 场景优化，体积小巧性能优秀</li><li><a href="https://github.com/vega/vega-lite" target="_blank" rel="noreferrer">vega-lite</a> ⭐ 5.3k — 基于 Vega 构建的简洁交互式图形语法库，通过简化的 JSON 声明式配置快速创建常见图表，支持数据聚合、筛选和交互选择</li><li><a href="https://github.com/dromara/go-view" target="_blank" rel="noreferrer">go-view</a> ⭐ 5k — 低代码数据可视化大屏设计器，支持拖拽式配置、多种数据源接入和实时数据刷新，基于 Vue3 + Vite + ECharts 构建</li><li><a href="https://github.com/antvis/G2Plot" target="_blank" rel="noreferrer">@antv/g2plot</a> ⭐ 5k — 基于 G2 的交互式图表库，提供响应式图表配置和优雅的可视化样式，开箱即用</li><li><a href="https://github.com/alibaba/BizCharts" target="_blank" rel="noreferrer">BizCharts</a> ⭐ 4k — 阿里巴巴开源的 React 图表库，提供丰富的商务图表类型，可集成到 Vue 项目中</li><li><a href="https://github.com/nhnent/toast-ui.vue-chart" target="_blank" rel="noreferrer">Toast UI Vue Chart</a> ⭐ 3k — NHN (Naver) TOAST UI 图表库的 Vue 组件，基于 Chart.js 开发，提供友好的 Vue API</li><li><a href="https://github.com/VisActor/VChart" target="_blank" rel="noreferrer">@visactor/vchart</a> ⭐ 2.3k — 字节跳动 VisActor 跨平台图表库，支持多种图表类型、3D 可视化和动画过渡，可集成到 Vue 项目中</li><li><a href="https://github.com/graphieros/vue-data-ui" target="_blank" rel="noreferrer">vue-data-ui</a> ⭐ 1.5k — 基于 Vue 3 的数据可视化 UI 组件库，包含 60+ 图表类型，支持响应式设计和主题定制</li><li><a href="https://github.com/dongsuo/vue-data-board" target="_blank" rel="noreferrer">vue-data-board</a> ⭐ 1.3k — 基于 Vue 的 DIY 数据分析面板，支持拖拽生成图表、自定义数据大屏布局和实时数据展示</li><li><a href="https://github.com/ghalex/vue3-charts" target="_blank" rel="noreferrer">Vue3-Charts</a> ⭐ 1.2k — 基于 SVG 的 Vue 3 轻量图表库，提供折线图、柱状图、面积图等常用图表类型，API 简洁、高度可定制</li><li><a href="https://github.com/devstark-com/vue-google-charts" target="_blank" rel="noreferrer">Vue Google Charts</a> ⭐ 1k — Google Charts 的 Vue.js 封装，支持 Google 提供的所有图表类型和 Google Sheets 数据源集成</li><li><a href="https://github.com/ankane/vue-chartkick" target="_blank" rel="noreferrer">Vue Chartkick</a> ⭐ 1k — Chartkick 图表库的 Vue 组件，使用简单的语法快速生成图表，支持 Chart.js、Highcharts 和 Google Charts 后端</li><li><a href="https://github.com/highcharts/highcharts-vue" target="_blank" rel="noreferrer">Highcharts Vue</a> ⭐ 688 — Highcharts 官方 Vue 封装，支持 Vue 2/3，提供股票图、地图、甘特图等高级图表类型</li><li><a href="https://github.com/unovue/vue-charts" target="_blank" rel="noreferrer">VCCS</a> ⭐ 600 — Recharts 的 Vue 3 移植版本，提供组合式 API 图表组件，支持桑基图、旭日图、树图等高级图表类型</li><li><a href="https://github.com/frappe/charts" target="_blank" rel="noreferrer">Frappe Charts</a> ⭐ 15.2k — 零依赖的轻量级 SVG 图表库，提供柱状图、折线图、饼图、热力图等，颜色友好设计，Vue 项目可直接集成使用</li><li><a href="https://github.com/antvis/S2" target="_blank" rel="noreferrer">@antv/S2</a> ⭐ 4.5k — 蚂蚁集团开源的表格可视化引擎，支持多维交叉分析和透视表，提供 Vue 组件封装，适合数据分析和报表场景</li><li><a href="https://github.com/victorgarciaesgi/vue-chart-3" target="_blank" rel="noreferrer">vue-chart-3</a> ⭐ 317 — 基于 Chart.js 4 的 Vue3 图表封装组件，以声明式组件方式渲染各类图表，支持 TypeScript 和响应式数据更新。</li><li><a href="https://github.com/dumptyd/vue-css-donut-chart" target="_blank" rel="noreferrer">vue-css-donut-chart</a> ⭐ 126 — 纯 CSS 实现的轻量 Vue 环形图组件，无需 Canvas，支持多扇区比例展示与动态更新，适合简单的占比可视化。</li><li><a href="https://www.highcharts.com/" target="_blank" rel="noreferrer">Highcharts</a> ⭐ 12k — 功能强大的 JavaScript 图表库，支持 80+ 图表类型、股票图、地图和甘特图，提供丰富的交互和导出功能，Vue 项目中可通过官方 highcharts-vue 封装使用</li><li><a href="https://antv.antgroup.com/" target="_blank" rel="noreferrer">AntV</a> — 蚂蚁集团开源的可视化解决方案，包含 G2、G6、F2、L7、S2、X6 等子库，覆盖统计图表、图关系、地理空间、表格分析等多种可视化场景</li><li><a href="http://visactor.io/" target="_blank" rel="noreferrer">VisActor</a> — 字节跳动开源的可视化解决方案，包含 VChart（图表）、VTable（表格）、VGrammar（语法）、VRender（渲染引擎）等子库，支持跨平台渲染</li></ul><h2 id="echarts-扩展" tabindex="-1">ECharts 扩展 <a class="header-anchor" href="#echarts-扩展" aria-label="Permalink to “ECharts 扩展”">​</a></h2><ul><li><a href="https://github.com/ecomfe/echarts-gl" target="_blank" rel="noreferrer">ECharts GL</a> ⭐ 2k — Apache ECharts 的 WebGL 扩展，提供地球可视化、3D 散点图、3D 柱状图、3D 曲面图等 3D 图表能力和地理坐标系统</li><li><a href="https://github.com/ecomfe/echarts-liquidfill" target="_blank" rel="noreferrer">echarts-liquidfill</a> ⭐ 1.5k — Apache ECharts 水球图/液面图扩展插件，用于百分比数据的动态波浪可视化，支持 ECharts 5+</li><li><a href="https://github.com/ecomfe/echarts-wordcloud" target="_blank" rel="noreferrer">echarts-wordcloud</a> ⭐ 1.4k — Apache ECharts 词云图扩展插件，基于 wordcloud2.js 构建，支持自定义形状和样式</li><li><a href="https://github.com/plainheart/echarts-extension-amap" target="_blank" rel="noreferrer">echarts-extension-amap</a> ⭐ 1.2k — Apache ECharts 的高德地图扩展插件，支持在高德地图上展示散点图、线图、热力图和饼图等可视化类型，兼容 ECharts 4/5</li><li><a href="https://github.com/mapbox/mapbox-gl-draw" target="_blank" rel="noreferrer">mapbox-gl-draw</a> ⭐ 1.1k — Mapbox GL JS 的地图绘制工具插件，提供多边形、线条、点等图形的拖拽绘制和编辑功能，适用于地理数据标注和区域划分场景</li></ul><h2 id="echarts-实例与资源" tabindex="-1">ECharts 实例与资源 <a class="header-anchor" href="#echarts-实例与资源" aria-label="Permalink to “ECharts 实例与资源”">​</a></h2><ul><li><a href="https://echarts.apache.org/examples/zh/index.html" target="_blank" rel="noreferrer">ECharts 官方实例</a> — Apache ECharts 官方示例库，提供海量图表配置示例和可运行代码，是学习和查找图表实现的首选资源</li><li><a href="https://www.makeapie.cn/explore.html" target="_blank" rel="noreferrer">makeapie</a> — ECharts 社区图表示例分享平台，收录大量开发者上传的创意图表作品和配置代码，支持在线预览与复制</li><li><a href="https://echarts.zhangmuchen.top/#/index" target="_blank" rel="noreferrer">MCChart</a> — ECharts 图表示例集合站点，提供分类整理的图表 Demo 和可视化效果展示</li><li><a href="https://www.isqqw.com/" target="_blank" rel="noreferrer">isqqw</a> — ECharts 图表示例与可视化资源网站，提供多种图表类型的实例展示和配置参考</li><li><a href="https://echarts.apache.org/handbook/zh/get-started/" target="_blank" rel="noreferrer">ECharts 官方教学文档</a> — Apache ECharts 官方教程文档，从快速上手到进阶配置，系统讲解 ECharts 的使用方法和最佳实践</li><li><a href="https://github.com/ecomfe/awesome-echarts" target="_blank" rel="noreferrer">awesome-echarts</a> ⭐ 4k — Apache ECharts 生态精选资源列表，收录 ECharts 与 Vue/React 等框架的集成方案、扩展插件和社区工具</li></ul><h2 id="地理空间与地图" tabindex="-1">地理空间与地图 <a class="header-anchor" href="#地理空间与地图" aria-label="Permalink to “地理空间与地图”">​</a></h2><ul><li><a href="https://github.com/Leaflet/Leaflet" target="_blank" rel="noreferrer">Leaflet</a> ⭐ 40k — 移动端友好的开源交互式地图库，体积小巧约 39KB、API 简洁易用、插件生态丰富，是 Web 地图开发的标准库</li><li><a href="https://github.com/visgl/deck.gl" target="_blank" rel="noreferrer">Deck.gl</a> ⭐ 13k — Uber 开源的高性能 WebGL 地理空间数据可视化库，支持海量数据渲染、3D 地图效果和 GPU 加速计算</li><li><a href="https://github.com/openlayers/openlayers" target="_blank" rel="noreferrer">OpenLayers</a> ⭐ 12k — 高性能的 WebGIS 地图库，支持多种地图服务（WMS/WMTS/WFS）、矢量数据格式（GeoJSON/KML/GML）和丰富的投影坐标系</li><li><a href="https://github.com/CesiumGS/cesium" target="_blank" rel="noreferrer">Cesium</a> ⭐ 12k — 用于构建 3D 地球和地理空间应用的库，支持 3D Tiles、地形数据、卫星影像和时间动态可视化</li><li><a href="https://github.com/Turfjs/turf" target="_blank" rel="noreferrer">Turf.js</a> ⭐ 10k — 模块化地理空间分析引擎，提供缓冲区、交集、距离计算、空间统计等 150+ 空间分析算法</li><li><a href="https://github.com/mapbox/mapbox-gl-js" target="_blank" rel="noreferrer">Mapbox GL JS</a> ⭐ 10k — Mapbox 出品的 WebGL 地图渲染引擎，支持矢量瓦片、3D 地形、自定义样式和流畅的交互体验</li><li><a href="https://github.com/visgl/react-map-gl" target="_blank" rel="noreferrer">react-map-gl</a> ⭐ 8.4k — Uber 开源的 Mapbox GL JS React 封装库，提供友好的 React API，支持矢量瓦片、自定义样式和地理空间数据可视化，可通过适配集成到 Vue 项目</li><li><a href="https://github.com/antvis/L7" target="_blank" rel="noreferrer">@antv/l7</a> ⭐ 3.6k — 蚂蚁集团 AntV 地理空间数据可视分析引擎，基于 WebGL 构建，支持海量空间数据 2D/3D 渲染、热力图、蜂窝图、聚合图等 30+ 地图可视化类型</li><li><a href="https://github.com/maplibre/maplibre-gl-js" target="_blank" rel="noreferrer">MapLibre GL JS</a> ⭐ 2.2k — Mapbox GL JS 的开源社区分支，支持矢量瓦片渲染、自定义地图样式和 3D 地形，无需 API Key 即可免费使用</li><li><a href="https://github.com/Dafrok/vue-baidu-map" target="_blank" rel="noreferrer">Vue Baidu Map (Dafrok)</a> ⭐ 2k — 百度地图的 Vue 组件库，支持地图展示、标注点、信息窗口、路线规划等百度地图 API 功能</li><li><a href="https://github.com/zouyaoji/vue-cesium" target="_blank" rel="noreferrer">Vue Cesium (zouyaoji)</a> ⭐ 1.8k — Vue 3 的 CesiumJS 组件库，提供声明式的 Vue 组件 API 封装三维地球功能，支持 Vite 和 TypeScript</li><li><a href="https://github.com/antvis/L7Plot" target="_blank" rel="noreferrer">@antv/l7plot</a> ⭐ 1.5k — 基于 L7 封装的地理空间可视化图表库，提供开箱即用的飞线图、热力图、路径图等高级地理图表</li><li><a href="https://github.com/yangyanggu/vue-amap" target="_blank" rel="noreferrer">Vue AMAP</a> ⭐ 1k — 基于 Vue 3 和高德地图 2.0 的地图组件库，支持地图展示、标注、路径规划、行政区查询等完整高德地图 API 封装</li><li><a href="https://github.com/MelihAltintas/vue3-openlayers" target="_blank" rel="noreferrer">vue3-openlayers</a> ⭐ 1k — OpenLayers 6 的 Vue 3 组件，提供声明式地图组件、图层管理和丰富的地理空间交互功能</li><li><a href="https://github.com/vue-leaflet/vue-leaflet" target="_blank" rel="noreferrer">@vue-leaflet/vue-leaflet</a> ⭐ 1k — Leaflet 的 Vue 3 组件库，完全兼容 SSR，支持响应式数据绑定和 TypeScript</li><li><a href="https://github.com/soal/vue-mapbox" target="_blank" rel="noreferrer">vue-mapbox</a> ⭐ 800 — Vue 2 的 Mapbox GL JS 封装，以声明式 Vue 风格调用地图源、标注、导航控件等功能</li><li><a href="https://github.com/yue1123/vue3-baidu-map-gl" target="_blank" rel="noreferrer">vue3-baidu-map-gl</a> ⭐ 460 — 基于百度地图 WebGL 版 JavaScript GL API 封装的 Vue3 组件库，支持 3D 视角、海量覆盖物与完整 TS 类型，开箱即用。</li><li><a href="https://github.com/yangjianfei/vue-baidu-map-3x" target="_blank" rel="noreferrer">vue-baidu-map-3x</a> ⭐ 184 — vue-baidu-map 的 Vue3 版本，支持百度地图 API 2.0、3.0 和 WebGL 模式，提供地图、点标记、折线、多边形等常用地图组件封装。</li></ul><h2 id="图关系与网络可视化" tabindex="-1">图关系与网络可视化 <a class="header-anchor" href="#图关系与网络可视化" aria-label="Permalink to “图关系与网络可视化”">​</a></h2><ul><li><a href="https://github.com/antvis/g6" target="_blank" rel="noreferrer">@antv/g6</a> ⭐ 11k — 蚂蚁集团 AntV 图可视化引擎，用于绘制关系图、树图、流程图、力导向图等复杂网络结构，支持 3D 图布局和大规模图数据渲染</li><li><a href="https://github.com/cytoscape/cytoscape.js" target="_blank" rel="noreferrer">Cytoscape.js</a> ⭐ 10k — 图论分析与可视化库，支持复杂网络布局算法、图论计算、样式绑定和多种导出格式</li><li><a href="https://github.com/jacomyal/sigma.js" target="_blank" rel="noreferrer">Sigma.js</a> ⭐ 2.6k — 专注于大图数据的 WebGL 渲染器，通过 GPU 加速实现百万级节点和边的流畅交互，支持丰富的交互行为和社区布局算法</li><li><a href="https://github.com/seeksdream/relation-graph" target="_blank" rel="noreferrer">relation-graph</a> ⭐ 2.1k — Vue 关系图谱可视化组件，支持力导向图、树形图、组织架构图等多种布局，节点和连线高度可定制，适用于知识图谱和企业关系展示</li></ul><h2 id="表格与数据网格" tabindex="-1">表格与数据网格 <a class="header-anchor" href="#表格与数据网格" aria-label="Permalink to “表格与数据网格”">​</a></h2><ul><li><a href="https://github.com/TanStack/table" target="_blank" rel="noreferrer">TanStack Table</a> ⭐ 27k — 无头 UI 表格库，支持 TypeScript/JS、Vue、React、Solid、Svelte 等多框架，提供排序、分组、分页、过滤等可控的表格构建能力</li><li><a href="https://github.com/future-architect/cheetah-grid" target="_blank" rel="noreferrer">cheetah-grid</a> ⭐ 2.5k — 高性能 Canvas 数据表格库，支持百万级数据渲染、自定义单元格绘制和流畅的交互体验</li><li><a href="https://github.com/xaksis/vue-good-table" target="_blank" rel="noreferrer">vue-good-table</a> ⭐ 2k — 易于使用的 Vue.js 数据表格插件，支持排序、筛选、分页、行选择、列固定、服务端分页等功能</li><li><a href="https://github.com/VisActor/VTable" target="_blank" rel="noreferrer">@visactor/vtable</a> ⭐ 1.5k — 字节跳动 VisActor 高性能多维数据分析表格，支持大数据量虚拟滚动、自定义单元格、图表嵌入和交互式分析</li><li><a href="https://github.com/huangshuwei/vue-easytable" target="_blank" rel="noreferrer">vue-easytable</a> ⭐ 1k — 基于 Vue 2.x 的数据表格，支持虚拟滚动、固定行列、单元格合并、树形数据等企业级功能</li><li><a href="https://github.com/handsontable/vue-handsontable-official" target="_blank" rel="noreferrer">vue-handsontable-official</a> ⭐ 1k — Handsontable 电子表格的官方 Vue.js 封装，类 Excel 功能的数据网格，支持公式、格式化、验证等特性</li><li><a href="https://github.com/njleonzhang/vue-data-tables" target="_blank" rel="noreferrer">vue-data-tables</a> ⭐ 1k — 基于 Element UI 的 Vue 2.0 数据表格增强组件，提供更完善的表格功能和业务场景封装</li><li><a href="https://github.com/ratiw/vuetable-2" target="_blank" rel="noreferrer">vuetable-2</a> ⭐ 1k — 简化的 Vue 2.x 数据表格，支持 AJAX 数据加载、排序、分页和自定义字段渲染</li><li><a href="https://github.com/olifolkerd/tabulator" target="_blank" rel="noreferrer">tabulator</a> ⭐ 7.5k — 跨框架的高性能交互式数据表格库，支持虚拟 DOM、编辑、筛选、排序、分组与多种内置编辑器，可对接 Vue 项目。</li><li><a href="https://github.com/Happy-Coding-Clans/vue-easytable" target="_blank" rel="noreferrer">vue-easytable</a> ⭐ 3.8k — 高性能 Vue 数据表格组件，支持虚拟滚动、单元格编辑、列固定、筛选排序和类 Excel 操作，适合大数据量表格场景。</li><li><a href="https://github.com/huynhduc28051999/easytable" target="_blank" rel="noreferrer">@vue-table-easy/vue</a> ⭐ 70 — Vue3 重构的高性能表格组件（源自 vue-easytable），支持 30 万行虚拟滚动、单元格编辑、剪贴板和右键菜单等功能。</li><li><a href="https://github.com/revolist/revogrid" target="_blank" rel="noreferrer">RevoGrid</a> ⭐ 3.4k — 强大的虚拟化数据表格组件，融合 Excel 级特性与高性能渲染，支持 Vue/React/Angular/Svelte，适用于大数据量企业表格场景</li></ul><h2 id="流程图与节点编辑" tabindex="-1">流程图与节点编辑 <a class="header-anchor" href="#流程图与节点编辑" aria-label="Permalink to “流程图与节点编辑”">​</a></h2><ul><li><a href="https://github.com/jerosoler/Drawflow" target="_blank" rel="noreferrer">Drawflow</a> ⭐ 6k — 简洁的节点流编辑器库，支持 Vue，可用于构建数据流、可视化编程和工作流编辑器</li><li><a href="https://github.com/dagrejs/dagre" target="_blank" rel="noreferrer">Dagre</a> ⭐ 5.6k — JavaScript 有向图布局引擎，提供自动排列节点和边的能力，是构建流程图、依赖关系图的核心布局库</li><li><a href="https://github.com/alibaba/butterfly" target="_blank" rel="noreferrer">Butterfly</a> ⭐ 4.7k — 阿里巴巴开源的 JavaScript/React/Vue 流程图组件，专注于流布局领域，支持 DAG 图、BPMN 和思维导图</li><li><a href="https://github.com/bcakmakoglu/vue-flow" target="_blank" rel="noreferrer">vue-flow</a> ⭐ 3.2k — 高度可定制的 Vue 3 流程图/节点编辑器，支持自定义节点、边样式、拖拽布局、迷你地图、缩放平移和多种布局算法</li><li><a href="https://github.com/OXOYO/X-Flowchart-Vue" target="_blank" rel="noreferrer">X-Flowchart-Vue</a> ⭐ 1.5k — 基于 G6 和 Vue 的可视化图形编辑器，支持流程图、思维导图等多种图表类型的可视化编辑</li></ul><h2 id="甘特图与项目管理" tabindex="-1">甘特图与项目管理 <a class="header-anchor" href="#甘特图与项目管理" aria-label="Permalink to “甘特图与项目管理”">​</a></h2><ul><li><a href="https://github.com/frappe/gantt" target="_blank" rel="noreferrer">Frappe Gantt</a> ⭐ 5.3k — 现代化轻量级甘特图库，零依赖，支持日/周/月/年等多视图切换、拖拽任务、任务依赖关系，被 ERPNext 采用</li><li><a href="https://github.com/visjs/vis-timeline" target="_blank" rel="noreferrer">vis-timeline</a> ⭐ 2.4k — 交互式时间轴可视化库，支持自定义项目、分组、范围缩放和拖拽编辑，适用于项目计划和甘特图场景</li><li><a href="https://github.com/DHTMLX/gantt" target="_blank" rel="noreferrer">dhtmlx-gantt</a> ⭐ 1k — 企业级 JavaScript 甘特图库，支持任务依赖、资源分配、关键路径分析，提供丰富的拖拽交互、时间刻度自定义和导出功能</li><li><a href="https://github.com/zunnzunn/vue-ganttastic" target="_blank" rel="noreferrer">vue-ganttastic</a> ⭐ 1.5k — Vue 3 原生甘特图组件，支持任务拖拽编辑、时间线缩放、依赖关系配置，可直接在 Vue 项目中作为组件使用</li></ul><h2 id="树形结构与层级可视化" tabindex="-1">树形结构与层级可视化 <a class="header-anchor" href="#树形结构与层级可视化" aria-label="Permalink to “树形结构与层级可视化”">​</a></h2><ul><li><a href="https://github.com/wanglin2/mind-map" target="_blank" rel="noreferrer">mind-map</a> ⭐ 12k — 强大的思维导图库，支持多种布局（逻辑结构图、组织结构图、鱼骨图等）、富文本编辑、主题自定义和导入导出，基于 Vue 开发</li><li><a href="https://github.com/hizzgdev/jsmind" target="_blank" rel="noreferrer">jsmind</a> ⭐ 3.8k — 基于 JavaScript 的思维导图库，支持 SVG 和 Canvas 渲染，提供节点编辑、拖拽、主题定制和 FreeMind/XMind 格式导入</li><li><a href="https://github.com/fperucic/treant-js" target="_blank" rel="noreferrer">Treant.js</a> ⭐ 1.2k — 基于 SVG 的树形图绘制库，支持自定义 CSS 样式、拖拽节点、滚动器和丰富的树形布局选项</li><li><a href="https://github.com/vue-pivottable/vue3-pivottable" target="_blank" rel="noreferrer">vue3-pivottable</a> ⭐ 800 — 数据透视表的 Vue 3 实现，支持拖拽行列、数据聚合、多维数据分析和类 Excel 数据透视视图</li><li><a href="https://github.com/Hoogkamer/vue-org-chart" target="_blank" rel="noreferrer">vue-org-chart</a> ⭐ 600 — Vue 组织架构图组件，用于展示层级关系和树形结构数据，支持节点展开/折叠和自定义样式</li></ul><h2 id="canvas-与图形绘制" tabindex="-1">Canvas 与图形绘制 <a class="header-anchor" href="#canvas-与图形绘制" aria-label="Permalink to “Canvas 与图形绘制”">​</a></h2><ul><li><a href="https://github.com/pixijs/pixijs" target="_blank" rel="noreferrer">PixiJS</a> ⭐ 46k — 快速灵活的 2D WebGL 渲染引擎，支持场景图、精灵、动画、粒子效果和多点触控交互，是 HTML5 图形创作的首选引擎</li><li><a href="https://github.com/konvajs/konva" target="_blank" rel="noreferrer">Konva.js</a> ⭐ 14.4k — HTML5 Canvas 2D 框架，提供面向对象的 API 构建交互式画布应用，支持形状、动画、拖拽、滤镜和序列化，vue-konva 的底层引擎</li><li><a href="https://github.com/konvajs/vue-konva" target="_blank" rel="noreferrer">Vue Konva</a> ⭐ 1.3k — Konva.js HTML5 2D Canvas 库的 Vue.js 封装，用于在 Vue 中创建复杂的画布应用、图像编辑器和游戏界面</li><li><a href="https://github.com/troisjs/trois" target="_blank" rel="noreferrer">TroisJS</a> ⭐ 4.1k — Vue 3 的 Three.js 声明式封装，提供直观的 Vue 组件风格 3D 场景构建和模型渲染 API，支持灯光、材质和动画系统</li><li><a href="https://github.com/Tresjs/cientos" target="_blank" rel="noreferrer">Cientos</a> ⭐ 1.2k — TresJS 生态系统扩展包，提供开箱即用的 3D 抽象组件：轨道控制、环境贴图、粒子效果和物理模拟</li></ul><h2 id="网格布局与瀑布流" tabindex="-1">网格布局与瀑布流 <a class="header-anchor" href="#网格布局与瀑布流" aria-label="Permalink to “网格布局与瀑布流”">​</a></h2><ul><li><a href="https://github.com/desandro/masonry" target="_blank" rel="noreferrer">Masonry</a> ⭐ 16k — 瀑布流网格布局库，基于可用垂直空间自动优化元素位置，类似 Pinterest 的卡片排列效果，压缩后约 15KB</li><li><a href="https://github.com/haltu/muuri" target="_blank" rel="noreferrer">Muuri</a> ⭐ 14k — 响应式、可排序、可过滤、可拖拽的网格/瀑布流布局库，基于 Web Animations API 实现流畅的拖拽和重排动画</li></ul><h2 id="数据处理与工具集" tabindex="-1">数据处理与工具集 <a class="header-anchor" href="#数据处理与工具集" aria-label="Permalink to “数据处理与工具集”">​</a></h2><ul><li><a href="https://github.com/finos/perspective" target="_blank" rel="noreferrer">Perspective</a> ⭐ 9.3k — J.P. Morgan 开源的交互式数据分析与可视化组件，基于 WebAssembly 构建，专为大规模数据和实时流数据场景设计，支持数据透视、聚合和多种图表类型，可作为 Web Component 集成到 Vue 项目中</li><li><a href="https://github.com/mauricius/vue-draggable-resizable" target="_blank" rel="noreferrer">vue-draggable-resizable</a> ⭐ 6.7k — Vue 可拖拽可调整大小的组件，用于构建可交互的可视化面板和布局编辑器</li><li><a href="https://github.com/antvis/data-set" target="_blank" rel="noreferrer">@antv/data-set</a> ⭐ 2k — 蚂蚁集团 AntV 数据处理工具，提供数据转换、统计计算、数据连接、数据补全等数据处理能力</li></ul><h2 id="时序数据可视化" tabindex="-1">时序数据可视化 <a class="header-anchor" href="#时序数据可视化" aria-label="Permalink to “时序数据可视化”">​</a></h2><ul><li><a href="https://github.com/leeoniya/uPlot" target="_blank" rel="noreferrer">UPlot</a> ⭐ 9.4k — 超高性能时序图表库，60KB 大小，渲染百万数据点无压力，适合 Vue 项目中的实时监控和性能分析场景</li><li><a href="https://github.com/danvk/dygraphs" target="_blank" rel="noreferrer">Dygraphs</a> ⭐ 3.2k — JavaScript 时序数据可视化库，支持缩放、平移和误差带显示，Vue 中快速集成股票/监控等时序图表</li><li><a href="https://github.com/laurens94/vue-timeline-chart" target="_blank" rel="noreferrer">vue-timeline-chart</a> ⭐ 40 — 面向 Vue3 的时间线图表组件，支持在时间轴上绘制点、区间、标记和背景，可缩放和平移，适合监控回放与时间段分布展示。</li></ul><h2 id="bi商业智能工具" tabindex="-1">BI商业智能工具 <a class="header-anchor" href="#bi商业智能工具" aria-label="Permalink to “BI商业智能工具”">​</a></h2><ul><li><a href="https://github.com/apache/superset" target="_blank" rel="noreferrer">Apache Superset</a> ⭐ 67.3k — Apache 开源 BI 平台，支持 SQL 查询构建仪表盘和图表，Vue 前端界面，提供企业级数据探索和可视化分析</li><li><a href="https://github.com/metabase/metabase" target="_blank" rel="noreferrer">Metabase</a> ⭐ 43.4k — 开源 BI 工具，无需 SQL 即可创建仪表盘和报表，基于 Clojure+React+Node.js，为 Vue 项目提供数据分析方案参考</li></ul><h2 id="词云与文本可视化" tabindex="-1">词云与文本可视化 <a class="header-anchor" href="#词云与文本可视化" aria-label="Permalink to “词云与文本可视化”">​</a></h2><ul><li><a href="https://github.com/timdream/wordcloud2.js" target="_blank" rel="noreferrer">WordCloud2.js</a> ⭐ 2.5k — HTML5 Canvas 词云生成器，支持自定义形状遮罩和悬停交互，Vue 项目中快速集成词云可视化</li></ul><h2 id="地图可视化图层" tabindex="-1">地图可视化图层 <a class="header-anchor" href="#地图可视化图层" aria-label="Permalink to “地图可视化图层”">​</a></h2><ul><li><a href="https://github.com/keplergl/kepler.gl" target="_blank" rel="noreferrer">Kepler.gl Vue</a> ⭐ 11.3k — Uber 开源的大规模地理数据可视化工具，支持百万级数据点和 10+ 地图图层类型，Vue 项目中用于复杂地理分析</li></ul><h2 id="实时协作图表编辑" tabindex="-1">实时协作图表编辑 <a class="header-anchor" href="#实时协作图表编辑" aria-label="Permalink to “实时协作图表编辑”">​</a></h2><ul><li><a href="https://github.com/tldraw/tldraw" target="_blank" rel="noreferrer">Tldraw</a> ⭐ 40.3k — 开源协作白板绘图工具，支持Vue集成，实时多人协作绘图和图表编辑</li><li><a href="https://github.com/excalidraw/excalidraw" target="_blank" rel="noreferrer">Excalidraw</a> ⭐ 94.2k — 手绘风格白板图表工具，可嵌入Vue应用实现协作绘图和流程图绘制</li></ul><h2 id="代码架构可视化" tabindex="-1">代码架构可视化 <a class="header-anchor" href="#代码架构可视化" aria-label="Permalink to “代码架构可视化”">​</a></h2><ul><li><a href="https://github.com/sverweij/dependency-cruiser" target="_blank" rel="noreferrer">Vue Dependency Cruiser</a> ⭐ 5.9k — 可视化npm依赖关系图，Vue项目中展示模块间依赖和循环引用</li></ul><h2 id="思维导图与知识图谱" tabindex="-1">思维导图与知识图谱 <a class="header-anchor" href="#思维导图与知识图谱" aria-label="Permalink to “思维导图与知识图谱”">​</a></h2><ul><li><a href="https://github.com/markmap/markmap" target="_blank" rel="noreferrer">Markmap</a> ⭐ 13k — 将 Markdown 实时渲染为交互式思维导图，支持 Vue 项目集成与 VSCode 插件，适合知识整理与大纲可视化</li><li><a href="https://github.com/hellowuxin/vue3-mindmap" target="_blank" rel="noreferrer">vue3-mindmap</a> ⭐ 455 — 灵感源自 MindNode 的 Vue3 思维导图组件，支持节点拖拽、缩放平移、节点编辑、撤销重做和多种语言，适合头脑风暴与知识整理。</li></ul><h2 id="地图与地理信息" tabindex="-1">地图与地理信息 <a class="header-anchor" href="#地图与地理信息" aria-label="Permalink to “地图与地理信息”">​</a></h2><ul><li><a href="https://github.com/inocan-group/vue3-google-map" target="_blank" rel="noreferrer">vue3-google-map</a> ⭐ 378 — Vue 3 组合式 Google Maps 组件集，提供标记、多边形、热力图等声明式封装</li><li><a href="https://github.com/vinayakkulkarni/v-mapbox" target="_blank" rel="noreferrer">v-mapbox</a> ⭐ 187 — Mapbox GL / MapLibre GL 的 Vue 3 声明式封装，支持图层与交互</li></ul>',41)])])}const f=r(i,[["render",h]]);export{c as __pageData,f as default};
